float random( in vec2 s )
{
    return fract(sin(dot(s.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

// Smooth minimum : https://iquilezles.org/articles/smin
float smin( float a, float b, float k ) {
    float h = clamp( 0.5+0.5*(b-a)/k, 0.0, 1.0 );
    return mix( b, a, h ) - k*h*(1.0-h);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
 	vec2 uv = 2.0 * fragCoord.xy / iResolution.xy - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    vec3 col = vec3(0.0);
    float nP = 50.0;
    float tD = 100000.0;
    float tL = 0.0;

    for (float pIdx = 0.0; pIdx < nP; pIdx += 1.0) {
        float iTimeR = random(vec2(pIdx, pIdx) / nP) * nP + iTime;
        float pI = 1.0;
        float iIdx = 0.0;
        float pD = modf(iTimeR / pI, iIdx);
        float xO = random(vec2(pIdx, iIdx));
        float x1 = random(vec2(iIdx, pIdx));
        float w = 1.5;
        vec2 p = vec2(xO * w - (w * 0.5) + sin(iTimeR * (10.0 * x1) + iIdx) * 0.1, 0.0 + pD * 2.0);
        p -= vec2(0.0, 1.0);
        float d = distance(p, uv);
        float l = (x1 - pD);
        tD = smin(d, tD, 0.15);
        d = min(d, 0.4);
        float id = 0.4 - d;
        tL += id * (l + 0.5);
    }

    col = vec3(1.0 - tD) * vec3(2.0, 1.0, 0.0) * (tL + 0.25);
    fragColor = vec4(col,1.0);
}
